// 你的专业是（/onboard/major）—— 2026-08-20 按 BOSS 截图顺序重排：
// 输入框 + 联想候选（标注 13:04：输「经济」出所有带经济字样的专业），
// 副行回显上一屏选好的学校名。答案落 简历教育[0].专业。
//
// Task 4：Backend 分支按需 查询Taxonomy('majors', { q, limit })（专业无层级，
// 只发 q + cursor）；点候选才存 专业引用，继续输入清除旧引用，
// 没点候选时阻止保存。Mock 分支保持本地 专业名录 不变。
// Task 5：下一步按钮绑定引用有效性（Backend 没点候选即禁用，提交守卫保留），
// 搜索态如实展示 加载中/没有匹配结果/加载失败，请求序守 stale response。
//
// 候选 onboarding 简历预填（Spec §8 /onboard/major）：首挂载同步用 取专业预填
// 初始化文本与引用 —— exact Catalog 命中带 canonical 引用，unresolved 只落
// source_name 文本（既有选择器守卫保持关闭），当前文本非空原样保留；
// 确认 major 分区只在既有保存成功后、跳转之前。

import { useEffect, useRef, useState } from 'react';
import 样式 from './入职引导.module.css';
import { 次级页外壳, 返回栏, 页面大标题, 主按钮, 滚动区 } from '../组件/通用';
import { 轻提示 } from '../组件/轻提示';
import { use导航 } from '../路由/导航钩子';
import { use应用状态 } from '../状态/应用状态';
import { 取后端错误文案 } from '../数据/HTTP客户端';
import { 取专业预填 } from '../流程/候选Onboarding简历预填';
import { 并入建档草稿 } from '../流程/onboarding配置';
import { 创建空候选预填状态 } from '../状态/后端/类型';
import { 路径 } from '../路由/路径表';
import { 专业名录 } from '../数据/专业名录';
import { 合并目录页 } from '../数据/目录选择';
import type { BFFTaxonomyItem } from '../数据/BFF契约';
import type { 目录选择值 } from '../数据/招聘数据源类型';

const 搜索防抖毫秒 = 250;

// Task 5：搜索状态机——加载中 / 成功（空结果给「没有匹配结果」）/ 失败
type 搜索阶段 = 'idle' | 'loading' | 'success' | 'error';

export default function 选专业() {
  const { 跳转, 返回 } = use导航();
  const { 状态: 全局, 操作, 数据源模式, 目录查询, 后端状态 } = use应用状态();
  const 是后端 = 数据源模式 === 'backend';
  // J-PILOT-02 Task 4：同 毕业院校 —— 这条教育段还不完整，BFF 跳过它，
  // 上一屏的学校只在建档草稿里，这一屏必须在同一条草稿段上补专业。
  // 旅程标记见 基本信息.tsx（日常编辑不写草稿）
  const 旅程中 = 是后端 && 全局.引导预填 !== null;
  const 建档 = 旅程中 ? 全局.引导预填?.建档 : undefined;
  const 草稿基本 = 建档?.资料?.基本信息;
  const 教育基底 = 建档?.资料?.教育 ?? 全局.简历教育;
  const 首段 = 教育基底[0];

  // 候选 onboarding 预填：首挂载同步初始化文本与引用（当前文本非空原样保留）
  const 专业初始 = 取专业预填(后端状态.候选预填状态 ?? 创建空候选预填状态(), 首段?.专业 ?? '', 首段?.专业引用);
  const [专业, 设专业] = useState(专业初始.text);
  // Task 5 修复：实际查询词与显示值分开——只有用户输入才更新它；点候选不改查询，
  // 否则短词变全名会触发清空/重查（闪烁），二次点选同名项则清列表后误报无结果。
  // 同时删除 Mock 的 已点选隐藏 / 精确匹配排除（选完不再隐藏全部候选）。
  const [查询词, 设查询词] = useState(专业初始.text.trim());
  // Backend：点候选后才落的引用；继续输入立即清空
  const [专业引用, 设专业引用] = useState<目录选择值 | undefined>(专业初始.ref);
  const [候选项, 设候选项] = useState<BFFTaxonomyItem[]>([]);
  // review-r2 R2-M-1：保留搜索的 nextCursor，滚到底加载第二页
  const [下一页游标, 设下一页游标] = useState<string | null>(null);
  const [加载中, 设加载中] = useState(false);
  const [搜索阶段, 设搜索阶段] = useState<搜索阶段>('idle');
  const 计时 = useRef(0);
  // review-r1 P2-2 / review-r2 R2-M-2 / Task 5：请求序 ref 守 stale response——
  // 每次输入变化（含清空）都递增，慢的旧搜索结果（含状态）不覆盖新的；
  // load-more 也捕获请求序，query 变了不追加。
  const 请求序 = useRef(0);
  const 方法引用 = useRef(目录查询?.查询Taxonomy);
  方法引用.current = 目录查询?.查询Taxonomy;

  const 词 = 专业.trim();
  // Task 5：Backend 没点候选（无引用）就不许继续；Mock 只看词非空
  const 不可继续 = 词 === '' || (是后端 && 专业引用 === undefined);

  // Backend 搜索：250ms debounce 后 查询Taxonomy('majors', { q, limit })
  // Task 5 修复：effect 只依赖实际查询词——点候选不改查询词，effect 不重跑、列表不闪
  useEffect(() => {
    if (!是后端) return;
    const 方法 = 方法引用.current;
    const trimmed = 查询词;
    // review-r3 R3-I-7：每次查询词变化都重置分页状态（候选/游标/加载），避免新词带着旧游标请求
    请求序.current += 1;
    设候选项([]);
    设下一页游标(null);
    设加载中(false);
    if (!方法 || trimmed === '') {
      // 空词 / 没有查询方法：回到 idle，不挂「加载中」
      设搜索阶段('idle');
      return;
    }
    // Task 5：非空词进入 loading（debounce 期间也算在途）
    设搜索阶段('loading');
    window.clearTimeout(计时.current);
    const 本次 = 请求序.current;
    计时.current = window.setTimeout(async () => {
      try {
        const 页 = await 方法('majors', { q: trimmed, limit: 20 });
        if (本次 !== 请求序.current) return;
        设候选项(页.items);
        设下一页游标(页.nextCursor);
        设搜索阶段('success');
      } catch {
        if (本次 !== 请求序.current) return;
        设候选项([]);
        设下一页游标(null);
        设搜索阶段('error');
      }
    }, 搜索防抖毫秒);
    return () => window.clearTimeout(计时.current);
  }, [查询词, 是后端]);

  // review-r2 R2-M-1：加载更多——用当前游标请求下一页，合并去重；请求序检查防 stale 追加
  const 加载更多 = async () => {
    if (下一页游标 === null || 加载中) return;
    const 方法 = 方法引用.current;
    if (!方法) return;
    const 本次 = 请求序.current;
    设加载中(true);
    try {
      const 页 = await 方法('majors', { q: 查询词, cursor: 下一页游标, limit: 20 });
      if (本次 !== 请求序.current) return;
      设候选项((旧) => 合并目录页(旧, 页.items));
      设下一页游标(页.nextCursor);
    } catch {
      if (本次 !== 请求序.current) return;
    } finally {
      if (本次 === 请求序.current) 设加载中(false);
    }
  };

  // Mock 候选：本地名录过滤。Task 5 修复：删除 已点选隐藏 与 精确匹配排除——
  // 点选后列表保持并标记选中；输入完整名称时同名候选仍出现。保持原有自由文本下一步语义。
  // review-r1 F5：按实际查询词过滤（点选只改显示值，按显示值过滤会把兄弟候选挤掉）。
  const mock候选 = 查询词 === '' ? [] : 专业名录.filter((名) => 名.includes(查询词));

  /** 同名专业按稳定 ID 区分：写草稿时专业文本与引用一起落，改文字即作废旧引用。 */
  const 写教育草稿 = (改: { 专业: string; 专业引用?: 目录选择值 }) => {
    if (!旅程中 || 首段 === undefined) return;
    操作.更新候选建档草稿(并入建档草稿(建档, {
      资料: {
        教育: 教育基底.map((条, 序) => (序 === 0 ? { ...条, 专业: 改.专业, 专业引用: 改.专业引用 } : 条)),
      },
    }));
  };

  // Task 5 修复：点候选只更新显示值与引用，不清结果、不改当前查询及游标——
  // 列表保持、已选状态可见、重复点选稳定，API 不因选择额外调用
  const 选候选 = (项: BFFTaxonomyItem) => {
    设专业(项.display_name);
    设专业引用({ id: 项.id, display_name: 项.display_name });
    写教育草稿({ 专业: 项.display_name, 专业引用: { id: 项.id, display_name: 项.display_name } });
  };

  const 选Mock候选 = (名: string) => {
    设专业(名);
  };

  const 输入改变 = (值: string) => {
    设专业(值);
    // 只有用户真实输入才更新实际查询词（点候选不动查询）
    设查询词(值.trim());
    if (专业引用 !== undefined) 设专业引用(undefined);
    写教育草稿({ 专业: 值 });
  };

  const 下一步 = async () => {
    if (词 === '') {
      轻提示('先填专业名称');
      return;
    }
    // Backend：没点过候选 → 阻止保存
    if (是后端 && 专业引用 === undefined) {
      轻提示('请从候选专业中选择');
      return;
    }
    const 新教育 = 教育基底.map((条, 序) => (序 === 0 ? { ...条, 专业: 词, 专业引用 } : 条));
    if (旅程中) 操作.更新候选建档草稿(并入建档草稿(建档, { 资料: { 教育: 新教育 } }));
    try {
      await 操作.保存简历({
        // 与四连屏其余各页同一表达式：刷新后姓名/生日只在草稿里，不能发空 profile
        基本信息: { ...全局.基本信息, ...草稿基本 },
        个人优势: 全局.个人优势,
        技能: 全局.简历技能,
        经历: 全局.简历经历,
        教育: 新教育,
        证书: 全局.简历证书,
      });
      // 预填确认只在既有保存成功后（拒绝时分区不确认），且先于跳转
      操作.确认候选Onboarding预填分区('major');
      跳转(路径.就读时间段);
    } catch (错误) {
      轻提示(取后端错误文案(错误));
    }
  };

  return (
    <次级页外壳 白底>
      <返回栏 返回={返回} />

      {/* 副行回显学校名：确认「填的是这所学校的专业」 */}
      <页面大标题 标题="你的专业是" 说明={首段?.学校 || undefined} />

      <滚动区 样式覆盖={{ padding: '14px 22px 12px' }}>
        <div className={样式.输入行}>
          <input
            className={样式.输入}
            placeholder="专业名称"
            value={专业}
            onChange={(事件) => 输入改变(事件.target.value)}
          />
        </div>

        {/* 联想候选：与毕业院校页同款行样式 */}
        <div className={样式.候选列表}>
          {是后端
            ? 候选项.map((项) => (
                <button
                  key={项.id}
                  className={`${样式.候选行} ${专业引用?.id === 项.id ? 样式.候选行选中 : ''} 可点`}
                  onClick={() => 选候选(项)}
                >
                  <span>{项.display_name}</span>
                  {/* Task 5 修复：选中按引用 ID 判断，同名不同 ID 不误打勾 */}
                  {专业引用?.id === 项.id ? <span className={样式.候选勾}>✓</span> : null}
                </button>
              ))
            : mock候选.map((名) => (
                <button
                  key={名}
                  className={`${样式.候选行} ${名 === 词 ? 样式.候选行选中 : ''} 可点`}
                  onClick={() => 选Mock候选(名)}
                >
                  <span>{名}</span>
                  {名 === 词 ? <span className={样式.候选勾}>✓</span> : null}
                </button>
              ))}
          {/* review-r2 R2-M-1：搜索返回 nextCursor 时显示「加载更多」，点击追加下一页 */}
          {是后端 && 下一页游标 !== null ? (
            <button className={`${样式.候选行} 可点`} onClick={加载更多} disabled={加载中} aria-label="加载更多">
              {加载中 ? '加载中…' : '加载更多'}
            </button>
          ) : null}
        </div>

        {/* Task 5：如实的搜索状态——在途 / 空结果 / 失败（Mock 分支永远 idle 不显示） */}
        {搜索阶段 === 'loading' ? <div role="status">加载中…</div> : null}
        {搜索阶段 === 'success' && 候选项.length === 0 ? (
          <div role="status">没有匹配结果，试试缩短关键词</div>
        ) : null}
        {搜索阶段 === 'error' ? <div role="alert">加载失败，请重试</div> : null}
      </滚动区>

      <主按钮 文字="下一步" 按下={下一步} 禁用={不可继续} />
    </次级页外壳>
  );
}